import{_ as t,o,c as n,a3 as a}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Invoices — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Invoices — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/invoices"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Invoices — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/invoices"}]]},"headers":[],"relativePath":"user-guide/invoices.md","filePath":"user-guide/invoices.md","lastUpdated":1787271837000}'),s={name:"user-guide/invoices.md"};function i(r,e,d,l,c,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="invoices-—-user-guide" tabindex="-1">Invoices — User Guide <a class="header-anchor" href="#invoices-—-user-guide" aria-label="Permalink to &quot;Invoices — User Guide&quot;">​</a></h1><h2 id="who-can-use-invoices" tabindex="-1">Who can use Invoices <a class="header-anchor" href="#who-can-use-invoices" aria-label="Permalink to &quot;Who can use Invoices&quot;">​</a></h2><p>Your workspace must have the <strong>Invoices</strong> module installed (free from Marketplace — not auto-installed, and <strong>no other module is required first</strong>). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>send</code>, <code>void</code> as needed).</p><p>Without <strong>assign</strong>, you only see invoices assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Invoices</strong> from the sidebar (<strong>Billing</strong>). Search by title or number, filter by status or assignee, toggle <strong>My invoices</strong> or <strong>Overdue only</strong>, and switch KPI cards (Total, My Invoices, Draft, Sent, Overdue) to quick-filter the table. The table shows total, balance due, due date, and the <strong>latest note</strong>; hover a truncated preview to read the full note.</p><ul><li>A <strong>Partial</strong> badge appears when an invoice is <strong>Unpaid</strong> but has payments posted (<code>amount_paid &gt; 0</code>) and a remaining balance (<code>balance_due &gt; 0</code>). This is display-only — the stored status stays <strong>Unpaid</strong> until the balance clears.</li><li>An <strong>Overdue</strong> badge appears next to the status badge for unpaid invoices past their due date</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted invoice from the row menu</li><li><strong>Delete permanently</strong> requires <code>invoices.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New invoice</strong></li><li>Enter a title, optional contact/company link (when Contacts/Companies is installed), optional linked quotation, currency (defaults to your workspace currency; full shared currency list), issue date, due date, notes, and optional <strong>Terms &amp; conditions</strong> (rich text — headings, lists, bold/italic/underline)</li><li>Choose a shared <strong>line discount type</strong> (none, percent, or fixed), then add lines. When <strong>Products</strong> is installed, optionally <strong>select a product</strong> to auto-fill name, details (from the product description), and unit price — you can still edit those fields. Lines also include Qty, Discount value (when type is not none), Tax %, with optional rich-text <strong>Details</strong> under each row — subtotal, discount, tax, and total update automatically. Tax is applied after line discounts. The totals panel also shows <strong>Paid</strong>, <strong>Credits</strong>, and <strong>Balance due</strong> on existing invoices.</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save with <strong>Create</strong> (returns to the list) or <strong>Create &amp; View</strong> (opens the record). Invoices also offer <strong>Create &amp; Send</strong>.</li></ol><p>Edit from the row menu or the record page while the invoice is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Send</strong>, content is locked; use status actions and assignment instead.</p><h2 id="recurring-invoices" tabindex="-1">Recurring invoices <a class="header-anchor" href="#recurring-invoices" aria-label="Permalink to &quot;Recurring invoices&quot;">​</a></h2><p>Turn on <strong>Recurring invoice</strong> when you create (or edit a draft). Choose a frequency (weekly, monthly, quarterly, semi-annually, or yearly). <strong>Next invoice date</strong> fills automatically — one week, month, quarter, six months, or year after the issue date (or after today if the issue date is empty). Month-end dates stay in range (31 January monthly → 28 February). You can still pick a different date. After that, later invoices follow the frequency from the next-invoice date. Optional end date stops generation after that date.</p><p>The first invoice is a normal invoice. After you <strong>Send</strong> it, EloSync creates the <strong>next</strong> invoice as a <strong>Draft</strong> on the <strong>Next invoice date</strong> you chose (workspace timezone), copying line items, customer, currency, and assignee. Generated invoices do not copy payments or credits.</p><p>When a customer cancels:</p><ol><li>Open the original recurring invoice and click <strong>Stop recurring</strong>. No further invoices are created. Paid invoices stay paid.</li><li>Optionally check <strong>Also cancel the latest unpaid generated invoice</strong> if this period’s auto-created draft/unpaid invoice should not be collected. If that invoice already has a payment or credit, void the payment first or issue a <a href="/user-guide/credit-notes">credit note</a> instead.</li></ol><p>Stopping the series does <strong>not</strong> void history by itself.</p><h2 id="download-pdf" tabindex="-1">Download PDF <a class="header-anchor" href="#download-pdf" aria-label="Permalink to &quot;Download PDF&quot;">​</a></h2><p><strong>Download PDF</strong> is on the invoice record page and the row menu. It generates a branded PDF using your <strong>Settings → Branding</strong> button color, logo (when uploaded), company profile, and optional bank details — plus line items, subtotal/discount/tax/total breakdown, balance due, and the memo notes. Long notes and terms continue across as many pages as needed. When payments have been posted, the PDF includes a <strong>Payments received</strong> table (date, payment number, method, reference, amount). A <strong>Partial</strong> chip appears when the invoice is unpaid with partial payments. Configure missing company/payment fields under Branding. Sending still does not email the customer.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>An invoice starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Send</strong> (<code>draft → unpaid</code>) — marks the invoice as unpaid in the CRM (does not e-mail the customer); sets the issue date to today if it wasn&#39;t set. If the invoice is recurring, this also starts the series.</li><li><strong>Cancel</strong> — available from Draft or Unpaid only; permanently cancels the invoice (<code>cancelled</code>). Blocked once any payment has been posted or any credit note applied — void the payments first (an applied credit note can&#39;t be undone at all). Partial payments keep the invoice <strong>Unpaid</strong> until the balance clears.</li></ul><p><strong>Paid</strong> is set automatically when Payments (or credits) bring the balance to zero.</p><p>Invalid transitions (e.g. sending an already-cancelled invoice) are rejected with a validation error.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Overview</strong> — shows the invoice memo from the create/edit <strong>Notes</strong> field (also printed on the PDF)</li><li><strong>Notes</strong> tab — internal activity notes the team adds after the invoice exists (not the same as the memo)</li><li><strong>Timeline</strong> — create, update, assignment, status change, note, void, delete/restore, and recurring start/stop/generate events</li></ul><h2 id="related-payments-and-credit-notes" tabindex="-1">Related payments and credit notes <a class="header-anchor" href="#related-payments-and-credit-notes" aria-label="Permalink to &quot;Related payments and credit notes&quot;">​</a></h2><p>If the <a href="/user-guide/payments">Payments</a> module is installed and you have <code>payments.view</code>, the invoice record page shows a <strong>Related payments</strong> link to jump to the Payments module and record or review payments against this invoice. If <a href="/user-guide/credit-notes">Credit Notes</a> is installed and you have <code>credit-notes.view</code>, a <strong>Credit notes</strong> link does the same for credit notes issued against this invoice.</p><p>Converted invoices also show the source <strong>Quotation</strong>, <strong>Estimate</strong>, and/or <strong>Contract</strong> when those links are set.</p><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>E-mailing invoices to customers (with or without the PDF attached) is still planned — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p>',32)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
